<?php
/** php tests/player-live-clock.php — deterministic overlay transitions without network. */
if ( 'cli' !== PHP_SAPI ) { http_response_code( 404 ); exit; }
define( 'ABSPATH', __DIR__ );
define( 'MINUTE_IN_SECONDS', 60 ); define( 'HOUR_IN_SECONDS', 3600 ); define( 'DAY_IN_SECONDS', 86400 ); define( 'WEEK_IN_SECONDS', 604800 );
define( 'BSC_TV_URL', 'https://example.test/bsc-tv/' );
require dirname( __DIR__ ) . '/includes/player.php';
require dirname( __DIR__ ) . '/includes/player-schedule.php';
require dirname( __DIR__ ) . '/includes/music.php';
$checks = 0;
function live_check( $ok, $label ) { global $checks; ++$checks; if ( ! $ok ) { throw new RuntimeException( $label ); } }
function live_media( $id, $now ) { return array( 'key' => 'youtube:' . $id, 'show_id' => $id, 'channel_id' => $id, 'resource' => array( 'platform' => 'youtube', 'id' => $id ), 'duration' => 3600, 'published_at' => $now - DAY_IN_SECONDS, 'premiere' => false, 'creator_key' => (string) $id ); }
$now = 1805806800;
$pool = array_column( array( live_media( 1, $now ), live_media( 2, $now ), live_media( 3, $now ) ), null, 'key' );
$settings = array( 'enabled' => true, 'recent' => 'rotation', 'repeat_hours' => 0, 'live_clock' => true, 'live_lead' => 2, 'live_wait' => 120, 'music' => array( 'enabled' => false ) );
$state = BSC_TV_Player::advance( array(), $pool, array(), $settings, $now );
$state = BSC_TV_Player_Schedule::replenish( $state, $pool, $settings, $now, true );
$original = $state['plan'];
$announcement = array( 'key' => 'waiting:twitch:brew:1805808600', 'resource' => array( 'platform' => 'twitch', 'id' => 'brew' ), 'show_id' => 0, 'channel_id' => 1, 'title' => 'Dégustation', 'start' => $now + 1680, 'expected_start' => $now + 1800, 'end' => 0, 'priority' => 50, 'standby' => true );
$settings['_announcements'] = array( $announcement );
$before = BSC_TV_Player::advance( $state, $pool, array(), $settings, $now + 1679 );
live_check( empty( $before['standby'] ) && empty( $before['live'] ), 'Replay continues before the configured lead time' );
$wait = BSC_TV_Player::advance( $before, $pool, array(), $settings, $now + 1680 );
live_check( $wait['standby']['key'] === $announcement['key'], 'Standby starts at the exact pre-live boundary' );
live_check( $wait['vod'] === $state['vod'] && $wait['plan'] === $original, 'Waiting never changes the base slot or queued timestamps' );
live_check( $wait['aired'][0]['end'] === $now + 1680, 'The interrupted replay is clipped in actual broadcast history' );
$long_wait = BSC_TV_Player::advance( $wait, $pool, array(), $settings, $now + 2200 );
live_check( $wait === $long_wait, 'A late start keeps looping without consuming or shifting the grid' );
$ident = BSC_TV_Player_Live::decorate( $wait['standby'], $settings, $now + 1682 );
$ident2 = BSC_TV_Player_Live::decorate( $wait['standby'], $settings, $now + 1693 );
$ident3 = BSC_TV_Player_Live::decorate( $wait['standby'], $settings, $now + 1704 );
live_check( 'identity' === $ident['resource']['platform'] && $ident['standby'] && ! $ident['live'], 'Waiting is a BSC identity, never a fabricated confirmed live' );
live_check( $ident['identity']['entry_video'] !== $ident2['identity']['entry_video'], 'BSC animations alternate during standby' );
live_check( $ident['identity']['entry_video'] === $ident3['identity']['entry_video'] && 2 === $ident3['offset'], 'The shared cycle loops at the correct offset' );
$live = array( 'key' => 'live:twitch:brew:123', 'resource' => $announcement['resource'], 'channel_id' => 1, 'show_id' => 0, 'title' => 'Vrai direct', 'start' => $now + 2000, 'end' => 0, 'priority' => 50, 'confirmed_at' => $now + 2200 );
$on = BSC_TV_Player::advance( $long_wait, $pool, array( $live['key'] => $live ), $settings, $now + 2200 );
live_check( $on['live']['key'] === $live['key'] && empty( $on['standby'] ), 'Confirmed live immediately replaces waiting animations' );
live_check( $on['plan'] === $original && 0 === $on['paused_at'], 'Live is an overlay, never a paused replay clock' );
$other = $live; $other['key'] = 'live:other'; $other['priority'] = 99;
$overrun = BSC_TV_Player::advance( $on, $pool, array( $live['key'] => $live, $other['key'] => $other ), $settings, $now + 15000 );
live_check( $overrun['live']['key'] === $live['key'], 'Ongoing live is stable even when another higher-priority source appears' );
live_check( $overrun['plan'] === $original, 'An overrun does not move or consume any background slots' );
$end = $now + 8100;
$resume = BSC_TV_Player::advance( $on, $pool, array(), $settings, $end );
$expected = array_values( array_filter( $original, static function ( $row ) use ( $end ) { return $row['start'] <= $end && $row['end'] > $end; } ) )[0];
live_check( empty( $resume['live'] ) && empty( $resume['standby'] ), 'Ended live cannot re-enter its stale announcement' );
live_check( $resume['vod']['key'] === $expected['key'] && $resume['vod']['start'] === $expected['start'] && $resume['vod']['end'] === $expected['end'], 'Resume joins the originally scheduled programme, not the interrupted one' );
live_check( $end - $resume['vod']['start'] === 900, 'Resume joins fifteen minutes into the programme' );
live_check( $resume['aired'][ count( $resume['aired'] ) - 1 ]['start'] === $end, 'Actual broadcast history starts at the resume time' );
live_check( count( array_filter( $resume['aired'], static function ( $row ) use ( $now, $end ) { return empty( $row['live'] ) && empty( $row['standby'] ) && $row['start'] > $now + 1680 && $row['start'] < $end; } ) ) === 0, 'Slots hidden by live are not logged as actually broadcast' );
live_check( $resume['plan'][0]['start'] === $expected['end'], 'The programme after resume keeps its initial start time' );
$refresh = BSC_TV_Player_Schedule::replenish( $on, $pool, $settings + array( 'max_channel_streak' => 2 ), $now + 2500, true );
live_check( array_slice( $refresh['plan'], 0, count( $original ) ) === $original, 'Catalogue refresh during live preserves the saved background grid' );
$early_end = BSC_TV_Player::advance( $on, $pool, array(), $settings, $now + 2300 );
live_check( $early_end['vod']['start'] === $state['vod']['start'] && 2300 === $now + 2300 - $early_end['vod']['start'], 'Short live resumes at the current original offset' );
$cancelled = $settings; $cancelled['_announcements'] = array();
$cancel = BSC_TV_Player::advance( $wait, $pool, array(), $cancelled, $now + 1750 );
live_check( empty( $cancel['standby'] ) && 1750 === $now + 1750 - $cancel['vod']['start'], 'Removing or cancelling an announcement resumes the clock immediately' );
$timeout = BSC_TV_Player::advance( $wait, $pool, array(), $settings, $now + 9000 );
live_check( empty( $timeout['standby'] ), 'A never-started announcement respects the configured waiting limit' );
$unlimited = $settings; $unlimited['live_wait'] = 0;
live_check( ! empty( BSC_TV_Player::advance( $wait, $pool, array(), $unlimited, $now + 9000 )['standby'] ), 'Zero waiting limit means unlimited standby, not a cap on live' );
$music_settings = $settings; $music_settings['_announcements'] = array();
$music_settings['music'] = array( 'enabled' => true, 'threshold' => 600, 'flexible' => false, 'repeat_hours' => 0, 'live_policy' => 'finish' );
$music = live_media( 4, $now ); $music['key'] = 'music:4'; $music['duration'] = 142;
$music['music'] = array( 'clip_id' => 4, 'artist' => 'Fixture artist', 'title' => 'Fixture clip', 'entry' => 11, 'duration' => 120, 'exit' => 11 );
$music_pool = $pool + array( $music['key'] => $music );
$music_state = $state; $music_state['aired'] = array();
$music_state['vod'] = BSC_TV_Player::begin( $music + array( 'available' => $now + 100 ), $music_state );
$music_live = $live; $music_live['start'] = $now + 105;
$interrupted = BSC_TV_Player::advance( $music_state, $music_pool, array( $music_live['key'] => $music_live ), $music_settings, $now + 110 );
live_check( ! empty( $interrupted['live'] ), 'Confirmed live interrupts music even with a legacy finish-music preference' );
live_check( $interrupted['plan'] === $music_state['plan'] && $interrupted['vod'] === $music_state['vod'], 'Music interruption does not delete breaks, alter their reserved durations or shift programmes' );
$back_to_clip = BSC_TV_Player::advance( $interrupted, $music_pool, array(), $music_settings, $now + 130 );
live_check( ! empty( $back_to_clip['vod']['music'] ) && 30 === $now + 130 - $back_to_clip['vod']['start'] && $back_to_clip['vod']['end'] === $now + 242, 'A short live can rejoin an interlude at its original phase and offset' );
$late_visitor = BSC_TV_Player::advance( $state, $pool, array(), $settings, $now + 2300 );
live_check( $late_visitor['standby']['start'] === $now + 1680, 'A late visitor discovers the same waiting boundary rather than starting a new clock' );
$rescheduled = $settings; $rescheduled['_announcements'][0]['key'] .= ':postponed'; $rescheduled['_announcements'][0]['start'] += 3600; $rescheduled['_announcements'][0]['expected_start'] += 3600;
live_check( empty( BSC_TV_Player::advance( $wait, $pool, array(), $rescheduled, $now + 1750 )['standby'] ), 'A postponed live releases the antenna until its new lead time' );
$days = BSC_TV_Player_Schedule::days( $overrun, $now + 15000, 'UTC' );
foreach ( $days as $day ) { foreach ( $day['rows'] as $row ) { live_check( empty( $row['scheduled'] ) || $row['start'] > $now + 15000, 'Programme display excludes past slots hidden by live' ); } }
echo "OK $checks live wall-clock checks.\n";
